import React from 'react';

const OptimizeVideo = ({ videoUrl, selectedFeatures }) => {
  return (
    <div>
      <h1>Optimize Video</h1>
      <p>Video URL: {videoUrl}</p>
      <p>Selected Features: {selectedFeatures.join(', ')}</p>
      {/* Add the actual optimization logic here */}
    </div>
  );
};

export default OptimizeVideo;
